-- FULL-POTENTIAL FAMILY SHOWCASE SEED — DEMO/STAGING ONLY.
-- Replaces all family-domain demo data in the oldest active network with the same 60-person / 5-generation showcase used by Playground.
-- DO NOT run against a real production family whose data you want to keep.
begin;
do $$
declare nid uuid; gid1 uuid:='fb479cb2-6f1e-5cba-941d-acd0c433d62e'; gid2 uuid:='ae02b97b-0f06-58a7-902a-71241416f14c';
begin
  select id into nid from public.networks where status='active' and (lower(name) like '%nawal%' or lower(name) like '%naval%' or lower(name) like '%sample%' or slug='our-family') order by created_at limit 1;
  if nid is null then raise exception 'No safe demo/default family target found. Rename the intended demo family to include Nawal/Naval/Sample (or use slug our-family) before running this destructive seed.'; end if;
  update public.network_settings set name='Nawal Family Showcase',description='60 people across five generations with memories, milestones, places, community and contribution examples.' where network_id=nid;
  delete from public.community_event_responses where network_id=nid;
  delete from public.community_events where network_id=nid;
  delete from public.community_group_members where network_id=nid;
  delete from public.community_groups where network_id=nid;
  delete from public.contribution_suggestions where network_id=nid;
  delete from public.memory_people where network_id=nid;
  delete from public.memories where network_id=nid;
  delete from public.member_life_events where network_id=nid;
  delete from public.profile_submissions where network_id=nid;
  delete from public.family_relationships where network_id=nid;
  update public.network_memberships set member_id=null where network_id=nid;
  delete from public.family_members where network_id=nid;
end $$;
commit;
